/* ═══════════════════════════════════════════════════════════
   HELPERS
   ═══════════════════════════════════════════════════════════ */
export function compact(n){
  n = Number(n) || 0;
  if (n >= 1e9) return (n/1e9).toFixed(1).replace(/\.0$/,'') + 'B';
  if (n >= 1e6) return (n/1e6).toFixed(1).replace(/\.0$/,'') + 'M';
  if (n >= 1e3) return (n/1e3).toFixed(1).replace(/\.0$/,'') + 'K';
  return String(n);
}
export function esc(s){
  return String(s ?? '').replace(/[&<>"']/g, c =>
    ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
/* Only accept saved data that actually contains something.
   An empty object is NOT valid data — the bug that cost us earlier. */
export function isRealPayload(p){
  return p && typeof p === 'object' && !Array.isArray(p) && Object.keys(p).length > 0;
}
/* Merge saved data over defaults, so new fields never break old saves. */
export function hydrate(saved){
  const base = structuredClone(DEFAULTS);
  if (!isRealPayload(saved)) return base;
  return {
    ...base, ...saved,
    profile: { ...base.profile, ...(saved.profile || {}) },
    platforms: Array.isArray(saved.platforms) && saved.platforms.length
      ? saved.platforms.map(p => ({ ...p, top: Array.isArray(p.top) ? p.top : [] }))
      : base.platforms,
    albums: Array.isArray(saved.albums) && saved.albums.length
      ? saved.albums.map(a => ({ ...a, tracks: Array.isArray(a.tracks) ? a.tracks : [] }))
      : base.albums,
    facts:        Array.isArray(saved.facts)        ? saved.facts        : base.facts,
    achievements: Array.isArray(saved.achievements) ? saved.achievements : base.achievements,
    tours:        Array.isArray(saved.tours)        ? saved.tours        : base.tours,
    history:      Array.isArray(saved.history)      ? saved.history      : [],
    media: {
      story: Array.isArray(saved.media?.story) ? saved.media.story : base.media.story,
      voice: Array.isArray(saved.media?.voice) ? saved.media.voice : base.media.voice
    }
  };
}
